//
//  FaceMorph.swift
//  The Ideal Week
//
//  True shape-morph between the official "Face Rating N out of 7" artworks.
//  Each face's vector contours (left eye, right eye, mouth, tear) were
//  extracted offline from the shipped SVG/PNG art into 160 uniformly-sampled
//  points (normalized to the art's shared 674.8x706.34 viewBox) and are
//  interpolated point-wise as the score moves — integer scores render the
//  exact artwork; fractional scores morph smoothly between neighbours.
//  (Extraction pipeline: scratchpad facemorph/extract.py, 2026-07-15.)
//

import SwiftUI

enum FaceMorphData {
    static let pointsPerContour = 160
    static let featureCount = 4      // leftEye, rightEye, mouth, tear
    static let faceCount = 7
    /// The art viewBox aspect (width / height).
    static let aspect: CGFloat = 674.8 / 706.34

    /// faces[faceIndex 0...6][feature][point] — normalized 0...1 coordinates.
    static let faces: [[[CGPoint]]] = {
        guard let data = Data(base64Encoded: blobB64) else { return [] }
        let floats: [Float32] = data.withUnsafeBytes { Array($0.bindMemory(to: Float32.self)) }
        var result: [[[CGPoint]]] = []
        var i = 0
        for _ in 0..<faceCount {
            var feats: [[CGPoint]] = []
            for _ in 0..<featureCount {
                var pts: [CGPoint] = []
                pts.reserveCapacity(pointsPerContour)
                for _ in 0..<pointsPerContour {
                    pts.append(CGPoint(x: CGFloat(floats[i]), y: CGFloat(floats[i + 1])))
                    i += 2
                }
                feats.append(pts)
            }
            result.append(feats)
        }
        return result
    }()

    private static let blobB64 = ""
}

/// Morphing face driven by the continuous 1...7 review score (7 = happiest).
struct FaceMorphShape: Shape {
    var score: Double

    var animatableData: Double {
        get { score }
        set { score = newValue }
    }

    func path(in rect: CGRect) -> Path {
        let faces = FaceMorphData.faces
        guard faces.count == FaceMorphData.faceCount else { return Path() }

        let clamped = min(7.0, max(1.0, score))
        let lower = min(6, max(1, Int(clamped)))
        let t = CGFloat(clamped - Double(lower))
        let a = faces[lower - 1]
        let b = faces[lower]           // lower is 1...6 -> b is faces[1...6]

        // Aspect-fit the art's viewBox into rect, centered.
        let drawW: CGFloat
        let drawH: CGFloat
        if rect.width / rect.height > FaceMorphData.aspect {
            drawH = rect.height
            drawW = drawH * FaceMorphData.aspect
        } else {
            drawW = rect.width
            drawH = drawW / FaceMorphData.aspect
        }
        let offX = rect.minX + (rect.width - drawW) / 2
        let offY = rect.minY + (rect.height - drawH) / 2

        var path = Path()
        for f in 0..<FaceMorphData.featureCount {
            let pa = a[f], pb = b[f]
            var first = true
            for p in 0..<FaceMorphData.pointsPerContour {
                let x = (pa[p].x + (pb[p].x - pa[p].x) * t) * drawW + offX
                let y = (pa[p].y + (pb[p].y - pa[p].y) * t) * drawH + offY
                if first {
                    path.move(to: CGPoint(x: x, y: y))
                    first = false
                } else {
                    path.addLine(to: CGPoint(x: x, y: y))
                }
            }
            path.closeSubpath()
        }
        return path
    }
}
